const bi = (ru, uz) => ({ ru, uz });
function loc(value, lang = 'ru') {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string' || typeof value === 'number') return String(value);
  return value[lang] || value.ru || value.uz || '';
}
function hostLoc(value, mode = 'ru') {
  if (mode === 'both') {
    const ru = loc(value, 'ru');
    const uz = loc(value, 'uz');
    if (!uz || uz === ru) return ru;
    return `${ru}\n${uz}`;
  }
  return loc(value, mode);
}

